namespace RecipeShare.Models;

public class Recipe
{
    public int Id { get; set; }
    public string Title { get; set; } = string.Empty;
    public string Category { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
    public List<string> Ingredients { get; set; } = [];
    public List<string> Steps { get; set; } = [];
    public int TotalRatings { get; set; }
    public int RatingSum { get; set; }

    public double AverageRating => TotalRatings > 0 ? (double)RatingSum / TotalRatings : 0;
}

using RecipeShare.Models;

namespace RecipeShare.Services;

public class RecipeService
{
    private readonly List<Recipe> _recipes;
    private int _nextId;

    public RecipeService()
    {
        _recipes =
        [
            new Recipe
            {
                Id = 1, Title = "Classic Margherita Pizza", Category = "Italian",
                Description = "A simple, classic pizza with fresh mozzarella, tomatoes, and basil.",
                Ingredients = ["Pizza dough", "San Marzano tomatoes", "Fresh mozzarella", "Fresh basil", "Olive oil", "Salt"],
                Steps = [
                    "Preheat oven to 475°F (245°C) with a pizza stone.",
                    "Stretch dough into a 12-inch round.",
                    "Spread crushed tomatoes over dough, leaving a 1-inch border.",
                    "Tear mozzarella and distribute evenly.",
                    "Bake for 10-12 minutes until crust is golden.",
                    "Top with fresh basil and a drizzle of olive oil."
                ],
                TotalRatings = 24, RatingSum = 108
            },
            new Recipe
            {
                Id = 2, Title = "Spaghetti Carbonara", Category = "Italian",
                Description = "Creamy Roman pasta made with eggs, cheese, pancetta, and pepper.",
                Ingredients = ["Spaghetti", "Pancetta", "Eggs", "Pecorino Romano", "Black pepper"],
                Steps = [
                    "Cook spaghetti in salted boiling water until al dente.",
                    "Crisp pancetta in a skillet over medium heat.",
                    "Whisk eggs with grated Pecorino and pepper.",
                    "Toss hot pasta with pancetta, then remove from heat.",
                    "Quickly stir in egg mixture, tossing constantly to create a creamy sauce.",
                    "Serve immediately with extra cheese and pepper."
                ],
                TotalRatings = 18, RatingSum = 81
            },
            new Recipe
            {
                Id = 3, Title = "Chicken Tikka Masala", Category = "Indian",
                Description = "Tender chicken pieces in a rich, spiced tomato-cream sauce.",
                Ingredients = ["Chicken thighs", "Yogurt", "Garam masala", "Tomato sauce", "Heavy cream", "Onion", "Garlic", "Ginger"],
                Steps = [
                    "Marinate chicken in yogurt and spices for at least 1 hour.",
                    "Grill or broil chicken until lightly charred.",
                    "Sauté onion, garlic, and ginger until softened.",
                    "Add tomato sauce and spices, simmer 15 minutes.",
                    "Stir in cream and add chicken pieces.",
                    "Simmer 10 minutes and serve over basmati rice."
                ],
                TotalRatings = 31, RatingSum = 146
            },
            new Recipe
            {
                Id = 4, Title = "Vegetable Pad Thai", Category = "Thai",
                Description = "Stir-fried rice noodles with vegetables, peanuts, and tangy tamarind sauce.",
                Ingredients = ["Rice noodles", "Tofu", "Bean sprouts", "Carrots", "Scallions", "Peanuts", "Tamarind paste", "Fish sauce", "Lime"],
                Steps = [
                    "Soak rice noodles in warm water for 20 minutes, then drain.",
                    "Press and cube tofu, then pan-fry until golden.",
                    "Mix tamarind paste, fish sauce, sugar, and lime juice for the sauce.",
                    "Stir-fry vegetables over high heat for 2 minutes.",
                    "Add noodles and sauce, toss until coated.",
                    "Top with crushed peanuts, bean sprouts, and lime wedges."
                ],
                TotalRatings = 15, RatingSum = 63
            },
            new Recipe
            {
                Id = 5, Title = "Beef Tacos", Category = "Mexican",
                Description = "Seasoned ground beef in warm tortillas with fresh toppings.",
                Ingredients = ["Ground beef", "Taco seasoning", "Corn tortillas", "Lettuce", "Tomato", "Cheddar cheese", "Sour cream", "Salsa"],
                Steps = [
                    "Brown ground beef in a skillet, drain excess fat.",
                    "Add taco seasoning and water, simmer until thickened.",
                    "Warm tortillas in a dry skillet or microwave.",
                    "Fill tortillas with seasoned beef.",
                    "Top with lettuce, diced tomato, cheese, sour cream, and salsa.",
                    "Serve with lime wedges."
                ],
                TotalRatings = 22, RatingSum = 92
            },
            new Recipe
            {
                Id = 6, Title = "Chocolate Lava Cake", Category = "Desserts",
                Description = "Rich individual chocolate cakes with a molten center.",
                Ingredients = ["Dark chocolate", "Butter", "Eggs", "Sugar", "Flour", "Vanilla extract"],
                Steps = [
                    "Preheat oven to 425°F (220°C). Butter and flour four ramekins.",
                    "Melt chocolate and butter together, let cool slightly.",
                    "Whisk eggs, sugar, and vanilla until thick.",
                    "Fold chocolate mixture into eggs, then fold in flour.",
                    "Divide batter among ramekins.",
                    "Bake 12-14 minutes until edges are firm but center is soft.",
                    "Invert onto plates and serve immediately."
                ],
                TotalRatings = 28, RatingSum = 133
            },
            new Recipe
            {
                Id = 7, Title = "Greek Salad", Category = "Mediterranean",
                Description = "Fresh and vibrant salad with cucumbers, tomatoes, olives, and feta.",
                Ingredients = ["Cucumber", "Tomatoes", "Red onion", "Kalamata olives", "Feta cheese", "Olive oil", "Oregano", "Lemon juice"],
                Steps = [
                    "Chop cucumber, tomatoes, and red onion into chunks.",
                    "Combine vegetables in a large bowl.",
                    "Add olives and crumbled feta.",
                    "Drizzle with olive oil and lemon juice.",
                    "Sprinkle with oregano, season with salt and pepper.",
                    "Toss gently and serve."
                ],
                TotalRatings = 12, RatingSum = 50
            },
            new Recipe
            {
                Id = 8, Title = "Miso Ramen", Category = "Japanese",
                Description = "Hearty Japanese noodle soup with a rich miso-based broth.",
                Ingredients = ["Ramen noodles", "White miso paste", "Chicken broth", "Soy sauce", "Sesame oil", "Soft-boiled eggs", "Corn", "Scallions", "Nori"],
                Steps = [
                    "Bring chicken broth to a simmer.",
                    "Whisk in miso paste until dissolved. Add soy sauce and sesame oil.",
                    "Cook ramen noodles according to package directions.",
                    "Divide noodles among bowls and ladle broth over them.",
                    "Top with halved soft-boiled eggs, corn, sliced scallions, and nori.",
                    "Serve immediately."
                ],
                TotalRatings = 20, RatingSum = 90
            }
        ];
        _nextId = 9;
    }

    public List<string> GetCategories()
    {
        return _recipes.Select(r => r.Category).Distinct().OrderBy(c => c).ToList();
    }

    public List<Recipe> GetRecipesByCategory(string category)
    {
        return _recipes.Where(r => r.Category.Equals(category, StringComparison.OrdinalIgnoreCase)).ToList();
    }

    public Recipe? GetRecipeById(int id)
    {
        return _recipes.FirstOrDefault(r => r.Id == id);
    }

    public void AddRating(int recipeId, int stars)
    {
        var recipe = GetRecipeById(recipeId);
        if (recipe is not null && stars >= 1 && stars <= 5)
        {
            recipe.TotalRatings++;
            recipe.RatingSum += stars;
        }
    }

    public void AddRecipe(Recipe recipe)
    {
        recipe.Id = _nextId++;
        _recipes.Add(recipe);
    }

    public List<Recipe> GetFeaturedRecipes()
    {
        return _recipes.OrderByDescending(r => r.AverageRating).Take(4).ToList();
    }
}

