arguments.file_text:
@page "/"

<PageTitle>RecipeShare — Home</PageTitle>

<h1>Welcome to RecipeShare 🍳</h1>
<p class="lead">Discover, share, and rate delicious recipes from around the world.</p>

<h2>Browse by Category</h2>
<div class="row row-cols-1 row-cols-md-3 g-4 mb-4">
    @foreach (var category in Categories)
    {
        <div class="col">
            <div class="card h-100 shadow-sm">
                <div class="card-body text-center">
                    <h3 class="card-title">@GetEmoji(category) @category</h3>
                    <p class="card-text text-muted">@GetRecipeCount(category) recipes</p>
                    <a href="category/@category" class="btn btn-outline-primary">Browse</a>
                </div>
            </div>
        </div>
    }
</div>

<h2>Top Rated</h2>
<div class="row row-cols-1 row-cols-md-2 g-3">
    @foreach (var recipe in FeaturedRecipes)
    {
        <div class="col">
            <div class="card shadow-sm">
                <div class="card-body">
                    <h5 class="card-title">
                        <a href="recipe/@recipe.Id">@recipe.Title</a>
                    </h5>
                    <p class="card-text">@recipe.Description</p>
                    <span class="text-warning">@RenderStars(recipe.AverageRating)</span>
                    <span class="text-muted ms-1">(@recipe.TotalRatings ratings)</span>
                </div>
            </div>
        </div>
    }
</div>

@code {
    [Inject] private RecipeService RecipeService { get; set; } = default!;

    private List<string> Categories { get; set; } = [];
    private List<Recipe> FeaturedRecipes { get; set; } = [];

    protected override void OnInitialized()
    {
        Categories = RecipeService.GetCategories();
        FeaturedRecipes = RecipeService.GetFeaturedRecipes();
    }

    private int GetRecipeCount(string category) =>
        RecipeService.GetRecipesByCategory(category).Count;

    private string GetEmoji(string category) => category switch
    {
        "Italian" => "🇮🇹",
        "Indian" => "🇮🇳",
        "Thai" => "🇹🇭",
        "Mexican" => "🇲🇽",
        "Desserts" => "🍰",
        "Mediterranean" => "🫒",
        "Japanese" => "🇯🇵",
        _ => "🍽️"
    };

    private static string RenderStars(double rating)
    {
        int full = (int)Math.Round(rating);
        return new string('★', full) + new string('☆', 5 - full);
    }
}

@page "/categories"
@page "/category/{CategoryName}"

<PageTitle>@(CategoryName ?? "All Categories") — RecipeShare</PageTitle>

@if (CategoryName is null)
{
    <h1>All Categories</h1>
    <div class="list-group">
        @foreach (var cat in RecipeService.GetCategories())
        {
            <a href="category/@cat" class="list-group-item list-group-item-action d-flex justify-content-between align-items-center">
                @cat
                <span class="badge bg-primary rounded-pill">@RecipeService.GetRecipesByCategory(cat).Count</span>
            </a>
        }
    </div>
}
else
{
    <nav aria-label="breadcrumb">
        <ol class="breadcrumb">
            <li class="breadcrumb-item"><a href="categories">Categories</a></li>
            <li class="breadcrumb-item active">@CategoryName</li>
        </ol>
    </nav>

    <h1>@CategoryName Recipes</h1>

    @if (Recipes.Count == 0)
    {
        <div class="alert alert-info">No recipes found in this category.</div>
    }
    else
    {
        <div class="row row-cols-1 row-cols-md-2 g-3">
            @foreach (var recipe in Recipes)
            {
                <div class="col">
                    <div class="card shadow-sm h-100">
                        <div class="card-body">
                            <h5 class="card-title">
                                <a href="recipe/@recipe.Id">@recipe.Title</a>
                            </h5>
                            <p class="card-text">@recipe.Description</p>
                            <span class="text-warning">@RenderStars(recipe.AverageRating)</span>
                            <span class="text-muted ms-1">(@recipe.TotalRatings ratings)</span>
                        </div>
                    </div>
                </div>
            }
        </div>
    }
}

@code {
    [Parameter] public string? CategoryName { get; set; }
    [Inject] private RecipeService RecipeService { get; set; } = default!;

    private List<Recipe> Recipes { get; set; } = [];

    protected override void OnParametersSet()
    {
        if (CategoryName is not null)
        {
            Recipes = RecipeService.GetRecipesByCategory(CategoryName);
        }
    }

    private static string RenderStars(double rating)
    {
        int full = (int)Math.Round(rating);
        return new string('★', full) + new string('☆', 5 - full);
    }
}

@page "/recipe/{Id:int}"

<PageTitle>@(Recipe?.Title ?? "Recipe") — RecipeShare</PageTitle>

@if (Recipe is null)
{
    <div class="alert alert-warning">Recipe not found.</div>
}
else
{
    <nav aria-label="breadcrumb">
        <ol class="breadcrumb">
            <li class="breadcrumb-item"><a href="categories">Categories</a></li>
            <li class="breadcrumb-item"><a href="category/@Recipe.Category">@Recipe.Category</a></li>
            <li class="breadcrumb-item active">@Recipe.Title</li>
        </ol>
    </nav>

    <h1>@Recipe.Title</h1>
    <p class="lead">@Recipe.Description</p>
    <span class="badge bg-secondary mb-3">@Recipe.Category</span>

    <div class="mb-4">
        <StarRating RecipeId="Recipe.Id" @rendermode="InteractiveServer" />
    </div>

    <div class="row">
        <div class="col-md-4">
            <div class="card mb-3">
                <div class="card-header"><strong>Ingredients</strong></div>
                <ul class="list-group list-group-flush">
                    @foreach (var ingredient in Recipe.Ingredients)
                    {
                        <li class="list-group-item">@ingredient</li>
                    }
                </ul>
            </div>
        </div>

        <div class="col-md-8">
            <h3>Instructions</h3>
            <ol class="list-group list-group-numbered mb-4">
                @foreach (var step in Recipe.Steps)
                {
                    <li class="list-group-item">@step</li>
                }
            </ol>
        </div>
    </div>
}

@code {
    [Parameter] public int Id { get; set; }
