    }
}

@rendermode InteractiveServer

<div class="star-rating">
    <span class="me-2">Rate this recipe:</span>
    @for (int i = 1; i <= 5; i++)
    {
        var star = i;
        <span class="star @(star <= (HoverStar ?? SelectedStar) ? "star-filled" : "star-empty")"
              @onclick="() => SubmitRating(star)"
              @onmouseover="() => HoverStar = star"
              @onmouseout="() => HoverStar = null"
              role="button"
              title="@star star(s)">
            @(star <= (HoverStar ?? SelectedStar) ? "★" : "☆")
        </span>
    }

    @if (Submitted)
    {
        <span class="text-success ms-2">✓ Thanks for rating!</span>
    }

    <div class="text-muted small mt-1">
        Average: @Recipe?.AverageRating.ToString("F1") / 5
        (@Recipe?.TotalRatings ratings)
    </div>
</div>

@code {
    [Parameter] public int RecipeId { get; set; }
    [Inject] private RecipeService RecipeService { get; set; } = default!;

    private Recipe? Recipe { get; set; }
