toolArgs.file_text:
@page "/recipe/{Id:int}"

<PageTitle>@(Recipe?.Title ?? "Recipe") — RecipeShare</PageTitle>

@if (Recipe is null)
{
    <div class="alert alert-warning">Recipe not found.</div>
}
else
{
    <nav aria-label="breadcrumb">
        <ol class="breadcrumb">
            <li class="breadcrumb-item"><a href="categories">Categories</a></li>
            <li class="breadcrumb-item"><a href="category/@Recipe.Category">@Recipe.Category</a></li>
            <li class="breadcrumb-item active">@Recipe.Title</li>
        </ol>
    </nav>

    <h1>@Recipe.Title</h1>
    <p class="lead">@Recipe.Description</p>
    <span class="badge bg-secondary mb-3">@Recipe.Category</span>

    <div class="mb-4">
        <StarRating RecipeId="Recipe.Id" @rendermode="InteractiveServer" />
    </div>

    <div class="row">
        <div class="col-md-4">
            <div class="card mb-3">
                <div class="card-header"><strong>Ingredients</strong></div>
                <ul class="list-group list-group-flush">
                    @foreach (var ingredient in Recipe.Ingredients)
                    {
                        <li class="list-group-item">@ingredient</li>
                    }
                </ul>
            </div>
        </div>

        <div class="col-md-8">
            <h3>Instructions</h3>
            <ol class="list-group list-group-numbered mb-4">
                @foreach (var step in Recipe.Steps)
                {
                    <li class="list-group-item">@step</li>
                }
            </ol>
        </div>
    </div>
}

@code {
    [Parameter] public int Id { get; set; }
    [Inject] private RecipeService RecipeService { get; set; } = default!;

    private Recipe? Recipe { get; set; }

    protected override void OnParametersSet()
    {
        Recipe = RecipeService.GetRecipeById(Id);
    }
}

@rendermode InteractiveServer

<div class="star-rating">
    <span class="me-2">Rate this recipe:</span>
    @for (int i = 1; i <= 5; i++)
    {
        var star = i;
        <span class="star @(star <= (HoverStar ?? SelectedStar) ? "star-filled" : "star-empty")"
              @onclick="() => SubmitRating(star)"
              @onmouseover="() => HoverStar = star"
              @onmouseout="() => HoverStar = null"
              role="button"
              title="@star star(s)">
            @(star <= (HoverStar ?? SelectedStar) ? "★" : "☆")
        </span>
    }

    @if (Submitted)
    {
        <span class="text-success ms-2">✓ Thanks for rating!</span>
    }

    <div class="text-muted small mt-1">
        Average: @Recipe?.AverageRating.ToString("F1") / 5
        (@Recipe?.TotalRatings ratings)
    </div>
</div>

@code {
    [Parameter] public int RecipeId { get; set; }
    [Inject] private RecipeService RecipeService { get; set; } = default!;

    private Recipe? Recipe { get; set; }
    private int SelectedStar { get; set; }
    private int? HoverStar { get; set; }
    private bool Submitted { get; set; }

    protected override void OnParametersSet()
    {
        Recipe = RecipeService.GetRecipeById(RecipeId);
    }

    private void SubmitRating(int stars)
    {
        RecipeService.AddRating(RecipeId, stars);
        SelectedStar = stars;
        Submitted = true;
        Recipe = RecipeService.GetRecipeById(RecipeId);
    }
}

