@page "/"

<PageTitle>RecipeShare — Home</PageTitle>

<h1>Welcome to RecipeShare 🍳</h1>
<p class="lead">Discover, share, and rate delicious recipes from around the world.</p>

<h2>Browse by Category</h2>
<div class="row row-cols-1 row-cols-md-3 g-4 mb-4">
    @foreach (var category in Categories)
    {
        <div class="col">
            <div class="card h-100 shadow-sm">
                <div class="card-body text-center">
                    <h3 class="card-title">@GetEmoji(category) @category</h3>
                    <p class="card-text text-muted">@GetRecipeCount(category) recipes</p>
                    <a href="category/@category" class="btn btn-outline-primary">Browse</a>
                </div>
            </div>
        </div>
    }
</div>

<h2>Top Rated</h2>
<div class="row row-cols-1 row-cols-md-2 g-3">
    @foreach (var recipe in FeaturedRecipes)
    {
        <div class="col">
            <div class="card shadow-sm">
                <div class="card-body">
                    <h5 class="card-title">
                        <a href="recipe/@recipe.Id">@recipe.Title</a>
                    </h5>
                    <p class="card-text">@recipe.Description</p>
                    <span class="text-warning">@RenderStars(recipe.AverageRating)</span>
                    <span class="text-muted ms-1">(@recipe.TotalRatings ratings)</span>
                </div>
            </div>
        </div>
    }
</div>

@code {
    [Inject] private RecipeService RecipeService { get; set; } = default!;

    private List<string> Categories { get; set; } = [];
    private List<Recipe> FeaturedRecipes { get; set; } = [];

    protected override void OnInitialized()
    {
        Categories = RecipeService.GetCategories();
        FeaturedRecipes = RecipeService.GetFeaturedRecipes();
    }

    private int GetRecipeCount(string category) =>
        RecipeService.GetRecipesByCategory(category).Count;

    private string GetEmoji(string category) => category switch
    {
        "Italian" => "🇮🇹",
        "Indian" => "🇮🇳",
        "Thai" => "🇹🇭",
        "Mexican" => "🇲🇽",
        "Desserts" => "🍰",
        "Mediterranean" => "🫒",
        "Japanese" => "🇯🇵",
        _ => "🍽️"
    };

    private static string RenderStars(double rating)
    {
        int full = (int)Math.Round(rating);
        return new string('★', full) + new string('☆', 5 - full);
    }
}

